/* setReport */
INSERT INTO TM_REPORT (
            USER_NUMB
          , BOOK_NUMB
          , REPT_STAT
          , REPT_STDT
          , REPT_ENDT
          , REPT_GRDE
          , REPT_COLR
          , PUBC_YSNO
          , REPT_CNTN
          , REGI_DATE
          , UPDT_DATE
) VALUES (  #{userNumb}
          , #{bookNumb}
          , #{reptStat}
          , #{reptStdt}
          , #{reptEndt}
          , #{reptGrde}
          , #{reptColr}
          , #{pubcYsno}
          , #{reptCntn}
          , CURRENT_TIMESTAMP
          , CURRENT_TIMESTAMP
)

mapper.update:
UPDATE /* uptReport */
       TM_REPORT
   SET REPT_STAT = #{reptStat}
     , REPT_STDT = #{reptStdt}
     , REPT_ENDT = #{reptEndt}
     , REPT_GRDE = #{reptGrde}
     , REPT_COLR = #{reptColr}
     , PUBC_YSNO = #{pubcYsno}
     , REPT_CNTN = #{reptCntn}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE REPT_NUMB = #{reptNumb}
   AND USER_NUMB = #{userNumb}
   AND SHA2(CONCAT_WS('|'
            , COALESCE(REPT_STAT, '')
            , COALESCE(REPT_STDT, '')
            , COALESCE(REPT_ENDT, '')
            , COALESCE(REPT_GRDE, '')
            , COALESCE(REPT_COLR, '')
            , COALESCE(PUBC_YSNO, '')
            , COALESCE(REPT_CNTN, '')
       ), 256) = #{editVersion}

UPDATE /* uptReptStatusGrade */
       TM_REPORT

       REPT_STAT = #{reptStat}
     , REPT_GRDE = #{reptGrde}
     , PUBC_YSNO = #{pubcYsno}

     , REPT_ENDT = #{reptEndt}

     , UPDT_DATE = CURRENT_TIMESTAMP

 WHERE REPT_NUMB = #{reptNumb}
   AND USER_NUMB = #{userNumb}

