    DELETE /* delReportReplyLikes */ L
      FROM TB_LIKEXX L
INNER JOIN TB_REPLXX R
        ON R.REPL_NUMB = L.TAGT_NUMB
       AND R.REPT_NUMB = #{reptNumb}
INNER JOIN TM_REPORT P
        ON P.REPT_NUMB = R.REPT_NUMB
       AND P.USER_NUMB = #{userNumb}
     WHERE L.TAGT_TYPE = #{likeTargetReply}

    DELETE /* delReportReplies */ R
      FROM TB_REPLXX R
INNER JOIN TM_REPORT P
        ON P.REPT_NUMB = R.REPT_NUMB
       AND P.USER_NUMB = #{userNumb}
     WHERE R.REPT_NUMB = #{reptNumb}


    DELETE /* delReportLikes */ L
      FROM TB_LIKEXX L
INNER JOIN TM_REPORT P
        ON P.REPT_NUMB = L.TAGT_NUMB
       AND P.USER_NUMB = #{userNumb}
     WHERE L.TAGT_TYPE = #{likeTargetReport}
       AND L.TAGT_NUMB = #{reptNumb}

DELETE /* delReport */
  FROM TM_REPORT
 WHERE REPT_NUMB = #{reptNumb}
   AND USER_NUMB = #{userNumb}
